"""Keep custom server defaults portable in generated migration scripts."""

import sqlalchemy as sa
from sqlalchemy.dialects import mysql

from db.types import TimestampDefault


def render_item(type_, obj, autogen_context):
    if type_ == "type" and isinstance(obj, sa.Enum) and not isinstance(obj, mysql.ENUM):
        # SchemaType copying in SQLAlchemy can discard Enum variants during autogeneration.
        # Emit both representations explicitly so an autogenerated revision remains portable.
        autogen_context.imports.add("from sqlalchemy.dialects import mysql")
        values = ", ".join(repr(value) for value in obj.enums)
        return (
            f"sa.Enum({values}, name={obj.name!r}, native_enum=False, "
            f"create_constraint=True).with_variant(mysql.ENUM({values}), 'mysql')"
        )
    if type_ == "server_default" and isinstance(obj, sa.DefaultClause):
        if isinstance(obj.arg, TimestampDefault):
            autogen_context.imports.add("from db.types import TimestampDefault")
            return (
                f"TimestampDefault(on_update={obj.arg.on_update!r}, "
                f"microseconds={obj.arg.microseconds!r})"
            )
    return False
